import React, { useEffect, useState } from "react";
import { supabase } from "./supabaseClient"; // Import Supabase client
import "./DoctorDashboard.css";
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  BarElement,
  Title,
  Tooltip,
  Legend,
} from 'chart.js';
import { Bar } from 'react-chartjs-2';

// Register Chart.js components
ChartJS.register(
  CategoryScale,
  LinearScale,
  BarElement,
  Title,
  Tooltip,
  Legend
);

export default function DoctorDashboard() {
  const [notifications, setNotifications] = useState([]);
  const [patients, setPatients] = useState([]);
  const [loading, setLoading] = useState(true);
  const [selectedPatient, setSelectedPatient] = useState(null);
  const [patientMetrics, setPatientMetrics] = useState([]);
  useEffect(() => {
    // --- Initial Fetch of Notifications ---
    const fetchNotifications = async () => {
      setLoading(true);
      const { data, error } = await supabase
        .from("doctor_notifications")
        .select("*")
        .order("created_at", { ascending: false }); // Show newest first

      if (error) {
        console.error("Error fetching notifications:", error);
      } else {
        setNotifications(data);
      }
      setLoading(false);
    };

    // --- Fetch Patients ---
    const fetchPatients = async () => {
      const { data, error } = await supabase
        .from("patients") // Assuming you have a 'patients' table
        .select("id, name"); // Fetch patient ID and name

      if (error) {
        console.error("Error fetching patients:", error);
      } else {
        setPatients(data);
      }
    };

    // --- Initial Fetch of Notifications ---
    // We'll keep this here to show real-time updates, but the focus is now on patients

    fetchNotifications();
    fetchPatients();



    // --- Real-time Subscription for New Notifications ---
    const channel = supabase
      .channel('db-doctor_notifications')
      .on(
        'postgres_changes',
        { event: 'INSERT', schema: 'public', table: 'doctor_notifications' , filter: 'risk_level=eq.High'}, // Only listen for High risk notifications
        (payload) => {
          // Check if the notification is a new high-risk notification
          console.log("New notification received:", payload.new);
          // Add the new notification to the top of the list
          setNotifications(currentNotifications => [payload.new, ...currentNotifications]);
        }
      )
      .subscribe();

    // --- Cleanup ---
    // Unsubscribe from the channel when the component unmounts
    return () => {
      supabase.removeChannel(channel);
    };

  }, []); // Run only once when the component mounts

  const handlePatientClick = async (patientId) => {
    // Find the selected patient
    const patient = patients.find(p => p.id === patientId);
    setSelectedPatient(patient);

    // --- Fetch real health metrics for the selected patient from Supabase ---
    const { data, error } = await supabase
      .from("health_metrics") // Assuming you have a 'health_metrics' table
      .select("*")
      .eq("patient_id", patientId)
      .order("date", { ascending: true }); // Order by date

    if (error) console.error("Error fetching patient health metrics:", error);
    else setPatientMetrics(data);
  };

  // --- Prepare data for the Bar Chart ---
  const chartData = {
    labels: patientMetrics.map(metric => metric.date),
    datasets: [
      {
        label: 'Heart Rate',
        data: patientMetrics.map(metric => metric.heartRate),
        backgroundColor: 'rgba(75, 192, 192, 0.6)',
        borderColor: 'rgba(75, 192, 192, 1)',
        borderWidth: 1,
      },    ],
  };
  return (
    <div className="dashboard">
      {/* Header */}
      <header className="navbar">
        <div className="logo">🩺 Doctor Dashboard</div>
      </header>

      <div className="notifications-container">
        <h3>Real-Time High-Risk Notifications</h3>
        {loading ? (
          <p>Loading notifications...</p>
        ) : notifications.length === 0 ? (
          <p>No new patient notifications.</p>
        ) : (
          <ul className="notification-list">
            {notifications.map(notification => (
              <li key={notification.id} className={`notification-item risk-${String(notification.risk_level).toLowerCase()}`}>
                <div className="notification-header">
                    <span className="patient-name">Patient: {notification.patient_name}</span>
                    <span className="risk-level">{notification.risk_level} Risk</span>
                </div>
                <p className="notification-message">{notification.message}</p>
                <small className="notification-timestamp">
                  {new Date(notification.created_at).toLocaleString()}
                </small>
              </li>
            ))}
          </ul>
        )}
      </div> {/* End of notifications-container */}

      {/* Patients Section */}
      <div className="patients-container">
        <h3>Your Patients</h3>
        {patients.length === 0 ? (
          <p>No patients found.</p>
        ) : (
          <ul className="patient-list">
            {patients.map(patient => (
              <li
                key={patient.id}
                className={`patient-item ${selectedPatient && selectedPatient.id === patient.id ? 'selected' : ''}`}
                onClick={() => handlePatientClick(patient.id)}
              >
                {patient.name}
              </li>
            ))}
          </ul>
        )}
      </div> {/* End of patients-container */}

      {/* Patient Details Section */}
      {selectedPatient && (
        <div className="patient-details-container">
          <h3>Health Metrics for {selectedPatient.name}</h3>
          {patientMetrics.length === 0 ? (
            <p>No health metrics available for this patient.</p>
          ) : (
            // Render a chart or a list of metrics here
            <div className="health-metrics-chart"><Bar data={chartData} /></div>
          )}
        </div>
      )} {/* End of patient-details-container */}


      </div>
  );
}
