import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { FaUser, FaLock, FaIdBadge } from 'react-icons/fa';
import { supabase } from './supabaseClient'; // Import Supabase
import './LoginPage.css';

export default function LoginPage() {
  const navigate = useNavigate();
  const [role, setRole] = useState('patient');
  const [formData, setFormData] = useState({
    id: '',
    fullName: '',
    password: ''
  });
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  const handleInputChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
    setError('');
  };

  // Find a user in the new 'users' table
  const findUserByRoleId = async (id, role) => {
    const { data, error } = await supabase
      .from('users')
      .select('*')
      .eq('role_specific_id', id.trim())
      .eq('role', role)
      .single(); // We expect only one user with a given ID and role

    if (error) {
      console.log('Supabase query error:', error.message);
      return null;
    }
    return data;
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    setError('');

    const idField = role === 'patient' ? 'Patient ID' : 'Doctor ID';
    if (!formData.id || !formData.fullName || !formData.password) {
      setError('All fields are required.');
      setLoading(false);
      return;
    }

    // Check for user in Supabase
    const user = await findUserByRoleId(formData.id, role);
    
    if (user) {
      // Check if full name and password match
      if (
        user.full_name.trim().toLowerCase() === formData.fullName.trim().toLowerCase() &&
        user.password === formData.password // In a real app, use hashed password comparison
      ) {
        // Navigate to the correct dashboard on successful login
        const dashboardPath = role === 'patient' ? '/patient-dashboard' : '/doctor-dashboard';
        navigate(dashboardPath, { state: { name: user.full_name } });
      } else if (user.full_name.trim().toLowerCase() !== formData.fullName.trim().toLowerCase()) {
        setError('Full name does not match the given ID.');
      } else {
        setError('Incorrect password.');
      }
    } else {
      setError(`No account found with this ${idField}. Please sign up.`);
    }
    setLoading(false);
  };

  return (
    <div className="login-page">
      <h1 className="title">💙 DiabetesPrediction</h1>
      <div className="login-container">
        <div className="role-toggle">
          <button
            className={role === 'patient' ? 'active' : ''}
            onClick={() => { setRole('patient'); setError(''); setFormData({ id: '', fullName: '', password: '' }); }}
          >
            👤 Patient
          </button>
          <button
            className={role === 'doctor' ? 'active' : ''}
            onClick={() => { setRole('doctor'); setError(''); setFormData({ id: '', fullName: '', password: '' }); }}
          >
            🩺 Doctor
          </button>
        </div>
        <form onSubmit={handleSubmit}>
          <label>
            {role === 'patient' ? 'Patient ID' : 'Doctor ID'}
            <div className="input-icon">
              <FaIdBadge className="icon" />
              <input
                type="text"
                name="id"
                placeholder={role === 'patient' ? "Enter your Patient ID" : "Enter your Doctor ID"}
                value={formData.id}
                onChange={handleInputChange}
                required
              />
            </div>
          </label>
          <label>
            Full Name
            <div className="input-icon">
              <FaUser className="icon" />
              <input
                type="text"
                name="fullName"
                placeholder="Enter your full name"
                value={formData.fullName}
                onChange={handleInputChange}
                required
              />
            </div>
          </label>
          <label>
            Password
            <div className="input-icon">
              <FaLock className="icon" />
              <input
                type="password"
                name="password"
                placeholder="Enter your password"
                value={formData.password}
                onChange={handleInputChange}
                required
              />
            </div>
          </label>
          {error && (
            <div className="error-message">{error}</div>
          )}
          <button type="submit" className="submit-btn" disabled={loading}>
            {loading ? 'Please wait...' : 'Login'}
          </button>
          <div style={{ marginTop: '20px', textAlign: 'center' }}>
            <span>Don't have an account? </span>
            <button
              type="button"
              className="signup-link"
              style={{
                background: 'none',
                border: 'none',
                color: '#1976d2',
                cursor: 'pointer',
                textDecoration: 'underline',
                fontSize: '1rem'
              }}
              onClick={() => navigate('/signup')}
            >
              Sign Up
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}
